def begin(self, mode="WRITE", bookmarks=None, metadata=None, timeout=None, db=None, imp_user=None,
          dehydration_hooks=None, hydration_hooks=None):
    if mode not in ("READ", "WRITE"):
        raise ValueError("Mode must be 'READ' or 'WRITE'")
    if bookmarks is not None:
        bookmarks = list(bookmarks)
    if metadata is not None:
        metadata = dict(metadata)
    if timeout is not None:
        timeout = int(timeout * 1000)  # Convert seconds to milliseconds
    if db is not None and self.PROTOCOL_VERSION < (4, 0):
        raise ProtocolError("Database selection requires Bolt protocol version 4.0+")
    if imp_user is not None and self.PROTOCOL_VERSION < (4, 4):
        raise ProtocolError("User impersonation requires Bolt protocol version 4.4+")

    headers = self.get_base_headers()
    if mode == "READ":
        headers["mode"] = "r"
    else:
        headers["mode"] = "w"
    if bookmarks:
        headers["bookmarks"] = bookmarks
    if metadata:
        headers["metadata"] = metadata
    if timeout is not None:
        headers["timeout"] = timeout
    if db:
        headers["db"] = db
    if imp_user:
        headers["imp_user"] = imp_user

    self._append(b"\x01", headers, dehydration_hooks=dehydration_hooks, hydration_hooks=hydration_hooks)

