        metadata = {}
    if timeout is not None:
        timeout = int(timeout * 1000)  # Convert seconds to milliseconds
    else:
        timeout = -1
    if db is None:
        db = ""
    if imp_user is None:
        imp_user = ""

    self._append(b"\x01", (
        mode,
        list(bookmarks),
        metadata,
        timeout,
        db,
        imp_user
    ), dehydration_hooks=dehydration_hooks, hydration_hooks=hydration_hooks, handlers=handlers)

