def point_type(name, fields, srid_map):
    class Point:
        __slots__ = ('x', 'y', 'srid')

        def __init__(self, x, y, srid=None):
            self.x = x
            self.y = y
            self.srid = srid if srid is not None else getattr(self.__class__, 'srid', None)

        def __repr__(self):
            return f"{name}(x={self.x}, y={self.y}, srid={self.srid})"

        def __eq__(self, other):
            if not isinstance(other, Point):
                return NotImplemented
            return (self.x == other.x and self.y == other.y and self.srid == other.srid)

        def __hash__(self):
            return hash((self.x, self.y, self.srid))

    Point.__name__ = name
    Point.__qualname__ = name

    return Point

