import os
import subprocess
import sys
from typing import Iterable, List, Optional, Sequence, Union


def xargs(
    args: Sequence[str],
    input: Optional[Union[str, bytes]] = None,
    max_args: Optional[int] = None,
    max_lines: Optional[int] = None,
    max_chars: Optional[int] = None,
    max_procs: Optional[int] = None,
    verbose: bool = False,
    color: bool = False,
    target_concurrency: int = 1,
) -> subprocess.CompletedProcess:
    """
    A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    if max_args is None and max_lines is None:
        max_args = 1

    if input is None:
        stdin_data = sys.stdin.buffer.read()
    elif isinstance(input, str):
        stdin_data = input.encode(sys.getdefaultencoding())
    else:
        stdin_data = input

    if stdin_data:
        items = stdin_data.split(b"\0") if b"\0" in stdin_data else stdin_data.split()
    else:
        items = []

    if max_args is not None:
        chunk_size = max_args
    elif max_lines is not None:
        chunk_size = max_lines
    else:
        chunk_size = 1

    chunks = []
    current_chunk = []
    current_length = 0

    for item in items:
        item_str = item.decode(sys.getdefaultencoding())
        item_len = len(item_str) + 1  # +1 for space

        if max_chars is not None and current_length + item_len > max_chars:
            if current_chunk:
                chunks.append(current_chunk)
            current_chunk = [item_str]
            current_length = item_len
        else:
            if max_args is not None and len(current_chunk) >= max_args:
                chunks.append(current_chunk)
                current_chunk = [item_str]
                current_length = item_len
            elif max_lines is not None and len(current_chunk) >= max_lines:
                chunks.append(current_chunk)
                current_chunk = [item_str]
                current_length = item_len
            else:
                current_chunk.append(item_str)
                current_length += item_len

    if current_chunk:
        chunks.append(current_chunk)

    if not chunks:
        chunks = [[]]

    if verbose:
        for chunk in chunks:
            print(" ".join(args + chunk), file=sys.stderr)

    # Determine if we should use a pty
    use_pty = color and hasattr(os, "openpty")

    if max_procs is not None and max_procs > 1:
        import concurrent.futures

        results = []
        executor = concurrent.futures.ThreadPoolExecutor(max_workers=max_procs)

        def run_command(chunk):
            cmd = list(args) + chunk
            if use_pty:
                master_fd, slave_fd = os.openpty()
                try:
                    result = subprocess.run(
                        cmd,
                        stdin=subprocess.DEVNULL,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        close_fds=True,
                    )
                finally:
                    os.close(master_fd)
                    os.close(slave_fd)
            else:
                result = subprocess.run(
                    cmd,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                )
            return result

        futures = [executor.submit(run_command, chunk) for chunk in chunks]
        for future in concurrent.futures.as_completed(futures):
            results.append(future.result())

        # Return the last result
        last_result = results[-1] if results else subprocess.CompletedProcess(
            args, 0, b"", b""
        )
        return last_result
    else:
        result = None
        for chunk in chunks:
            cmd = list(args) + chunk
            if use_pty:
                master_fd, slave_fd = os.openpty()
                try:
                    result = subprocess.run(
                        cmd,
                        stdin=subprocess.DEVNULL,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        close_fds=True,
                    )
                finally:
                    os.close(master_fd)
                    os.close(slave_fd)
            else:
                result = subprocess.run(
                    cmd,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                )

        return result if result is not None else subprocess.CompletedProcess(
            args, 0, b"", b""
        )

