    exe = cmd[0]

    # If it's a shebang, we need to handle it specially
    if os.name == 'nt':
        # On Windows, we need to handle shebangs
        try:
            with open(exe, 'rb') as f:
                first_line = f.readline()
                if first_line.startswith(b'#!'):
                    # Parse shebang
                    shebang = first_line.decode('utf-8', errors='replace').strip()
                    # Extract interpreter and args
                    parts = shebang[2:].strip().split(None, 1)
                    if parts:
                        interpreter = parts[0]
                        # Try to find the interpreter
                        try:
                            interp_path = find_executable(interpreter)
                        except Exception:
                            interp_path = None
                        if interp_path:
                            # Replace the exe with the interpreter
                            if len(parts) > 1:
                                cmd = [interp_path] + [parts[1]]
                            else:
                                cmd = [interp_path]
                            # Recursively normalize the new command
                            return normalize_cmd(cmd)
        except Exception:
            pass

    # For Windows, we need to handle .bat and .cmd files
    if os.name == 'nt':
        # Try to find the executable with extensions
        for ext in ['.exe', '.bat', '.cmd', '.com']:
            try_path = exe + ext
            if os.path.exists(try_path):
                cmd[0] = os.path.abspath(try_path)
                break
        else:
            # If not found, try with the original path
            try:
                cmd[0] = os.path.abspath(exe)
            except Exception:
                cmd[0] = exe
    else:
        cmd[0] = os.path.abspath(exe)

    return cmd


def find_executable(exe: str, environ: Optional[dict] = None) -> str:
    """Find an executable in PATH."""
    if os.path.isabs(exe):
        return exe

    if os.name == 'nt':
        # On Windows, check if it already has an extension
        if '.' in exe:
            # Check if it exists as is
            if os.path.exists(exe):
                return exe
        else:
            # Try adding extensions
            for ext in ['.exe', '.bat', '.cmd', '.com']:
                try_path = exe + ext
                if os.path.exists(exe + ext):
                    return os.path.abspath(exe + ext)

    # Use shutil.which if available
    try:
        import shutil
        result = shutil.which(exe, mode=os.X_OK)
        if result is not None:
            return os.path.abspath(result)
    except Exception:
        pass

    # Fallback to PATH lookup
    path = environ.get('PATH', os.environ.get('PATH', os.defpath))
    for directory in path.split(os.path.pathsep):
        if not directory:
            continue
        full_path = os.path.join(directory, exe)
        if os.path.exists(full_path):
            return os.path.abspath(full_path)

    return exe

