import functools

def cachedmethod(cache, key=None, info=False):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Args:
        cache: The cache object to use for storing results.
        key: Optional function to generate cache key from arguments.
        info: If True, adds cache_info() method to wrapped function.

    Returns:
        A decorator function that wraps the target function with caching behavior.
    """
    def decorator(func):
        # Create cache storage for this decorated function
        cache_attr = '_cached_' + func.__name__

        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            # Generate cache key
            if key is None:
                cache_key = (args, tuple(sorted(kwargs.items())))
            else:
                cache_key = key(self, *args, **kwargs)

            # Try to get from cache
            try:
                cache = getattr(self, cache_attr)
            except AttributeError:
                # Initialize cache if not exists
                cache = cache()
                setattr(self, cache_attr, cache)

            try:
                return cache[cache_key]
            except KeyError:
                # Not in cache, compute result
                result = func(self, *args, **kwargs)
                cache[cache_key] = result
                return result

        if info:
            def cache_info():
                """Return cache statistics."""
                try:
                    cache = getattr(wrapper, cache_attr)
                    return len(cache)
                except AttributeError:
                    return 0

            def cache_clear():
                """Clear the cache."""
                try:
                    cache = getattr(wrapper, cache_attr)
                    cache.clear()
                except AttributeError:
                    pass

            wrapper.cache_info = cache_info
            wrapper.cache_clear = cache_clear

        return wrapper
    return decorator

