def extostr(self, e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        return str(e)

    lines = []
    lines.append("Exception Type: {0}".format(type(e).__name__))
    lines.append("Exception Message: {0}".format(str(e)))

    tb = traceback.extract_tb(e.__traceback__)
    if len(tb) > max_level:
        tb = tb[:max_level]

    lines.append("Traceback (most recent call last):")

    path_counts = {}
    for filename, line_num, func_name, text in tb:
        # Normalize path
        normalized_path = os.path.normpath(filename)

        # Count path occurrences
        path_counts[normalized_path] = path_counts.get(normalized_path, 0) + 1

        # Truncate path if needed
        path_parts = normalized_path.split(os.sep)
        if len(path_parts) > max_path_level:
            path_parts = path_parts[-max_path_level:]
            truncated_path = os.sep.join(path_parts)
            if path_counts[normalized_path] > 1:
                truncated_path = ".../" + truncated_path
        else:
            truncated_path = normalized_path

        lines.append('  File "{0}", line {1}, in {2}'.format(truncated_path, line_num, func_name))
        if text:
            lines.append('    {0}'.format(text.strip()))

    # Add exception chain if present
    cause = e.__cause__
    if cause:
        lines.append("")
        lines.append("The above exception was the direct cause of the following exception:")
        lines.append("")
        lines.append(self.extostr(cause, max_level, max_path_level))

    # Add context exception if present (when __suppress_context__ is False)
    if e.__context__ and not e.__suppress_context__:
        lines.append("")
        lines.append("During handling of the above exception, another exception occurred:")
        lines.append("")
        lines.append(self.extostr(e.__context__, max_level, max_path_level))

    return "\n".join(lines)

