def _legacy_mergeOrderings(orderings):
    """
    Merge multiple orderings so that within-ordering order is preserved
    """
    if not orderings:
        return []

    # Start with the first ordering
    result = list(orderings[0])

    # Process remaining orderings
    for ordering in orderings[1:]:
        # For each element in the current ordering
        for elem in ordering:
            if elem not in result:
                # Find the rightmost position where we can insert this element
                # such that ordering constraints are preserved
                pos = 0
                for i, existing in enumerate(result):
                    if elem < existing:
                        pos = i
                        break
                    else:
                        pos = i + 1
                # Insert at the right position
                result.insert(pos, elem)

    return result

