def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent.

    Returns all classes without subclasses as a list.
    """
    if not classes:
        return []

    # Convert to list if not already
    classes = list(classes)

    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
        else:
            continue
        unique_classes.append(cls)

    # Remove classes that are subclasses of other classes in the list
    result = []
    for i, cls in enumerate(unique_classes):
        is_subclass_of_others = False
        for j, other in enumerate(unique_classes):
            if i != j and issubclass(cls, other):
                is_subclass_of_others = True
                break
        if not is_subclass_of_others:
            result.append(cls)

    return result

