def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    if isinstance(sequence, (list, tuple)):
        for item in sequence:
            _normalizeargs(item, output)
    else:
        # Check if it's an individual interface or implements spec
        # (i.e., not a Declaration or tuple)
        from zope.interface.interface import Interface
        from zope.interface.declarations import (
            BuiltinImplementationSpecifications,
            ProvidesClass,
            InstanceDeclarations,
        )

        # If it's a Declaration (ProvidesClass or InstanceDeclarations)
        if isinstance(sequence, (ProvidesClass, InstanceDeclarations)):
            # Expand the Declaration
            for iface in sequence:
                _normalizeargs(iface, output)
        # If it's a BuiltinImplementationSpecifications
        elif isinstance(sequence, BuiltinImplementationSpecifications):
            # Expand the specifications
            for iface in sequence:
                _normalizeargs(iface, output)
        # If it's a tuple (but not a Declaration)
        elif isinstance(sequence, tuple):
            _normalizeargs(sequence, output)
        # Otherwise, it's an individual interface or implements spec
        else:
            output.append(sequence)

    return output

