    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.
    """
    if not hasattr(context, 'error'):
        context.error = {}

    # Map coordinate names to x, y, z for first three coordinates
    coord_names = self._coord_names
    err_indices = self._get_err_indices()

    # Process error fields
    for field_name, indices in err_indices.items():
        # Parse error field name to get coordinate and error type
        # Format: error_<coord>_<type>
        match = re.match(r'error_(\w+)_(low|high)', field_name)
        if match:
            coord_name = match.group(1)
            error_type = match.group(2)

            # Map to x, y, z if it's one of the first three coordinates
            if coord_name in coord_names:
                idx = coord_names.index(coord_name)
                if idx < 3:
                    mapped_coord = ['x', 'y', 'z'][idx]
                else:
                    mapped_coord = coord_name
            else:
                mapped_coord = coord_name

            # Create nested structure in context.error
            if mapped_coord not in context.error:
                context.error[mapped_coord] = {}

            # Add error type with index
            error_key = f"{mapped_coord}_{error_type}"
            context.error[mapped_coord][error_key] = {"index": indices}

