def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Handle 1D case
    if len(edges) == 2 and isinstance(edges[0], (int, float)):
        # 1D histogram
        total = 0.0
        for i, bin_val in enumerate(bins):
            if i < len(edges) - 1:
                width = edges[i + 1] - edges[i]
                total += bin_val * width
        return total
    else:
        # Handle multi-dimensional case
        # edges is a list of arrays for each dimension
        # bins is a multi-dimensional array

        # Get number of dimensions
        ndim = len(edges)

        # Compute widths for each dimension
        widths = []
        for edge_arr in edges:
            dim_widths = []
            for i in range(len(edge_arr) - 1):
                dim_widths.append(edge_arr[i + 1] - edge_arr[i])
            widths.append(dim_widths)

        # Compute integral by summing over all cells
        total = 0.0
        # Create index iterators for each dimension
        indices = [range(len(bins)) if ndim == 1 else range(len(bins))] if ndim == 1 else [range(len(bins[i])) for i in range(len(bins))]

