def fill(self, coord, weight):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Check if coordinate is within bounds for all dimensions
    if len(coord) != self.dim:
        return

    for i, val in enumerate(coord):
        if val < self.edges[i][0] or val > self.edges[i][-1]:
            return

    # Find bin indices for each dimension
    indices = []
    for i, val in enumerate(coord):
        # Find the appropriate bin index for this dimension
        # Using linear search since edges might not be evenly spaced
        idx = -1
        for j in range(len(self.edges[i]) - 1):
            if self.edges[i][j] <= val <= self.edges[i][j + 1]:
                # Check if value is within this bin's range
                if i == 0:  # First dimension
                    if j == len(self.edges[i]) - 1:
                        if val == self.edges[i][j]:
                            idx = j
                            break
                    if self.edges[i][j] <= val < self.edges[i][j + 1]:
                        idx = j
                        break
                else:
                    if self.edges[i][j] <= val < self.edges[i][j + 1]:
                        idx = j
                        break
            if idx != -1:
                break
        if idx == -1:
            return  # Coordinate outside edges
        indices.append(idx)

    # Fill the histogram at the computed bin indices
    if len(indices) == self.dim:
        self.bins[tuple(indices)] += weight

