    if not isinstance(namespace, str):
        raise ValidationError("Namespace must be a string")
    if len(namespace) > 63 or not re.match(r"[a-z0-9]([a-z0-9-]*[a-z0-9])?", namespace):
        raise ValidationError(f"Invalid resource namespace: {namespace}")

def resource_ref(resource):
    if resource is None:
        return None
    if isinstance(resource, str):
        return resource
    elif isinstance(resource, dict):
        name = resource.get("name")
        namespace = resource.get("namespace")
        if name is None:
            raise ValidationError("Resource reference must contain 'name'")
        _validate_resource_name(name)
        _validate_resource_namespace(namespace)
        if namespace:
            return f"{namespace}/{name}"
        return name
    else:
        raise ValidationError("Resource reference must be a string or dictionary")

