def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    manifest = app.spec.manifest
    observer_schema = app.status.observer_schema or {}

    if isinstance(manifest, dict):
        default_schema = generate_default_observer_schema_dict(manifest, first_level=True)
    elif isinstance(manifest, list):
        default_schema = generate_default_observer_schema_list(manifest)
    else:
        return

    # Merge default schema with existing observer schema, prioritizing existing custom schemas
    for key, value in default_schema.items():
        if key not in observer_schema:
            observer_schema[key] = value

    app.status.observer_schema = observer_schema


def generate_default_observer_schema_dict(manifest_dict, first_level):
    """Generate default observer schema for a dictionary manifest."""
    schema = {}

    if first_level and "apiVersion" in manifest_dict and "kind" in manifest_dict:
        # For top-level resource, include metadata and spec by default
        schema["metadata"] = {"name": {}, "namespace": {}, "uid": {}, "resourceVersion": {}}
        schema["spec"] = {}
        schema["status"] = {}
    else:
        # For nested objects, include all keys recursively
        for key, value in manifest_dict.items():
            if isinstance(value, dict):
                schema[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                schema[key] = generate_default_observer_schema_list(value)
            else:
                schema[key] = {}

    return schema


def generate_default_observer_schema_list(manifest_list):
    """Generate default observer schema for a list manifest."""
    if not manifest_list:
        return []

