def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import logging
    import zipfile

    logger = logging.getLogger(__name__)

    def _group_files_by_xml_filename(source, xmls, files):
        """Group files by their XML basename."""
        grouped = {}
        for xml in xmls:
            basename = os.path.basename(xml)
            grouped[basename] = {
                "xml": xml,
                "files": [f for f in files if os.path.basename(f) == basename]
            }
        return grouped

    def explore_source(source):
        """Explore source (file or folder) and return files and XMLs."""
        if os.path.isfile(source):
            return [source], []
        elif os.path.isdir(source):
            files = []
            xmls = []
            for root, dirs, filenames in os.walk(source):
                for filename in filenames:
                    filepath = os.path.join(root, filename)
                    if filename.endswith('.xml'):
                        xmls.append(filepath)
                    else:
                        files.append(filepath)
            return files, xmls
        else:
            return [], []

    def _explore_folder(folder):
        """Explore folder and return files and XMLs."""
        return explore_source(folder)

    # Main logic
    try:
        files, xmls = _explore_folder(os.path.dirname(zip_path))
        result = _group_files_by_xml_filename(zip_path, xmls, files)
        return result
    except Exception as e:
        logger.error(f"Error exploring zip file: {e}")
        return {}

