                "source": source,
                "files": []
            }
        for file in files:
            basename = os.path.basename(file)
            if basename in grouped:
                grouped[basename]["files"].append(file)
            else:
                grouped[basename] = {
                    "xml": None,
                    "source": source,
                    "files": [file]
