        return []

    # Helper function to check if two expressions are equal
    def equal(a, b):
        return a == b

    # Helper function to check if expression is a NOT expression
    def is_not(expr):
        return isinstance(expr, tuple) and expr[0] == 'NOT'

    # Helper function to get the operand of a NOT expression
    def get_not_operand(expr):
        return expr[1] if isinstance(expr, tuple) and expr[0] == 'NOT' else None

    # Helper function to check if expression is AND
    def is_and(expr):
        return isinstance(expr, tuple) and expr[0] == 'AND'

    # Helper function to check if expression is OR
    def is_or(expr):
        return isinstance(expr, tuple) and expr[0] == 'OR'

    # Helper function to get arguments of AND/OR
    def get_args(expr):
        return expr[1:] if isinstance(expr, tuple) else [expr]

    # Helper function to build AND expression
    def make_and(*args):
        if len(args) == 1:
            return args[0]
        return ('AND',) + tuple(args)

    # Helper function to build OR expression
    def make_or(*args):
        if len(args) == 1:
            return args[0]
        return ('OR',) + tuple(args)

    # Helper function to check if expression contains another expression
    def contains(expr, subexpr):
        if equal(expr, subexpr):
            return True
        if is_and(expr) or is_or(expr):
            for arg in get_args(expr):
                if contains(arg, subexpr):
                    return True
        return False

    # Helper function to check if expression contains NOT of another expression
    def contains_not(expr, subexpr):
        if is_and(expr) or is_or(expr):
            for arg in get_args(expr):
                if is_not(arg) and equal(get_not_operand(arg), subexpr):
                    return True
        return False

    # Helper function to apply absorption to a pair
    def apply_absorption(a, b):
        # Positive absorption: A & (A | B) = A, A | (A & B) = A
        if is_and(a) and is_or(b):
            b_args = get_args(b)
            if a in b_args:
                return a
        elif is_or(a) and is_and(b):
            b_args = get_args(b)
            if a in b_args:
                return a

        # Negative absorption: A & (~A | B) = A & B, A | (~A & B) = A | B
        if is_and(a) and is_or(b):
            b_args = get_args(b)
            for b_arg in b_args:
                if is_not(b_arg):
                    not_operand = get_not_operand(b_arg)
                    if equal(not_operand, a):
                        # A & (~A | B) = A & B
                        new_b_args = [arg for arg in b_args if not equal(arg, b_arg)]
                        if new_b_args:
                            return make_and(a, *new_b_args)
                        else:
                            return a
        elif is_or(a) and is_and(b):
            b_args = get_args(b)
            for b_arg in b_args:
                if is_not(b_arg):
                    not_operand = get_not_operand(b_arg)
                    if equal(not_operand, a):
                        # A | (~A & B) = A | B
                        new_b_args = [arg for arg in b_args if not equal(arg, b_arg)]
                        if new_b_args:
                            return make_or(a, *new_b_args)
                        else:
                            return a

        return None

    # Apply absorption iteratively
    changed = True
    while changed:
        changed = False
        new_args = []
        i = 0
        while i < len(args):
            absorbed = False
            for j in range(len(args)):
                if i != j:
                    result = apply_absorption(args[i], args[j])
                    if result is not None:
                        new_args.append(result)
                        absorbed = True
                        changed = True
                        break

            if not absorbed:
                new_args.append(args[i])
            i += 1
        args = new_args

    # Remove duplicates while preserving order
    seen = set()
    result = []
    for arg in args:
        # Convert to hashable representation for set
        if isinstance(arg, tuple):
            arg_tuple = arg
        else:
            arg_tuple = (arg,)
        if arg_tuple not in seen:
            seen.add(arg_tuple)
            result.append(arg)

    return result

