                                result.append(self.AND(current, other_part))
                                absorbed = True
                                break
                # For OR: A | (~A & B) = A | B
                elif isinstance(other, self.AND):
                    for arg in other.args:
                        if is_complement(arg, current):
                            # Found complement, apply negative absorption
                            other_args = [x for x in other.args if x != arg]
                            if other_args:
                                other_part = other_args[0] if len(other_args) == 1 else self.AND(*other_args)
                                result.append(self.OR(current, other_part))
                                absorbed = True
                                break

        if not absorbed:
            result.append(current)
        i += 1

    # Simplify result by removing duplicates and applying idempotent laws
    unique_result = []
    for expr in result:
        if expr not in unique_result:
            unique_result.append(expr)

    return unique_result

