    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Validate root structure
    if not self.check_root_structure():
        self.traversal_error("root-structure")
        return 0, 0

    # Validate extensions directory if present
    if self.extension:
        self.validate_extensions_dir()

    # Process each object
    for object_path in self.object_paths():
        num_objects += 1
        try:
            # Try to open and validate the object
            obj = self.object_path(object_path)
            if validate_objects:
                result = obj.validate(check_digests=check_digests, show_warnings=show_warnings)
                if result:
                    good_objects += 1
            else:
                good_objects += 1
        except Exception as e:
            self.traversal_error("object-invalid")
            if show_warnings:
                self.log.warning(f"Object at {object_path} failed validation: {e}")

    return num_objects, good_objects

