import re
import sys
import fs
from fs import open_fs
import namaste


def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description
    """
    try:
        # Check if path exists
        root_fs = open_fs(path)

        # Look for 0= Namaste files
        namaste_files = []
        for item in root_fs.walk.files():
            filename = item.path.split('/')[-1]
            if re.match(r'^0=', filename):
                namaste_files.append(filename)

        if len(namaste_files) == 0:
            # No 0= files found
            return "no_namaste_file"

        # Read the first 0= file found
        if len(namaste_files) > 0:
            # Try to read the first 0= file
            try:
                with root_fs.open(namaste_files[0], 'r') as f:
                    content = f.read()
                    # Check for OCFL Object type
                    if "OCFL Object" in content:
                        return "object"
                    # Check for OCFL Root type
                    elif "OCFL Root" in content:
                        return "root"
                    else:
                        return "file"
            except Exception as e:
                return str(e)
        else:
            return "file"

    except Exception as e:
        return str(e)

