from collections.abc import Mapping

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
    ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If there are
    colliding keys with non-MappingNode values (e.g., integers or strings), the last of the values wins.
    """
    if not nodes:
        return nodes

    # Group nodes by their key (ScalarNode)
    merged = {}
    for key, value in nodes:
        if key not in merged:
            merged[key] = value
        else:
            # If both values are MappingNode, merge them recursively
