def deep_merge_nodes(nodes):
    """
    Given a list of (key_node, value_node) tuples, merge any value_nodes
    corresponding to duplicate key_nodes by deep-merging MappingNodes,
    and return the result. If there are colliding keys with non-MappingNode
    values, the last value wins.
    """
    # Dictionary to store merged results keyed by key_node.value (for ScalarNode)
    merged = {}

    for key_node, value_node in nodes:
        if isinstance(key_node, ScalarNode):
            key_value = key_node.value
        else:
            # For non-ScalarNode keys, use the node itself as the key
            key_value = key_node

        if key_value in merged:
            existing_value = merged[key_value]
            if isinstance(value_node, MappingNode) and isinstance(existing_value, MappingNode):
                # Deep merge the MappingNodes
                merged[key_value] = deep_merge_mapping_nodes(existing_value, value_node)
            else:
                # Non-MappingNode values: last wins
                merged[key_value] = value_node
        else:
            merged[key_value] = value_node

    # Convert back to list of tuples
    result = []
    for key_value, value_node in merged.items():
        # Find the original key_node that matches key_value
        for orig_key, _ in nodes:
            if isinstance(orig_key, ScalarNode) and orig_key.value == key_value:
                result.append((orig_key, value_node))
                break
        else:
            # If no match found, use the key_value as a new ScalarNode
            result.append((ScalarNode(tag='tag:yaml.org,2002:str', value=str(key_value)), value_node))

    return result


def deep_merge_mapping_nodes(base_node, override_node):
    """
    Deep merge two MappingNodes, with override_node values taking precedence.
    """
    # Convert MappingNodes to dictionaries for easier merging
    base_dict = {}
    for key_node, value_node in base_node.value:
        if isinstance(key_node, ScalarNode):
            key = key_node.value
        else:
            key = key_node
        base_dict[key] = value_node

    override_dict = {}
    for key_node, value_node in override_node.value:
        if isinstance(key_node, ScalarNode):
        key = key_node.value
        else:
            key = key_node
        override_dict[key] = value_node

    # Merge dictionaries
    for key, value in override_dict.items():
        if key in base_dict and isinstance(value, MappingNode) and isinstance(base_dict[key], MappingNode):
            base_dict[key] = deep_merge_mapping_nodes(base_dict[key], value)
        else:
            base_dict[key] = value

    # Convert back to list of tuples for MappingNode
    result = []
    for key, value in base_dict.items():
        if isinstance(key, ScalarNode):
            result.append((key, value))
        else:
            result.append((key, value))

    return MappingNode(tag='tag:yaml.org,2002:map', value=result)

