    Return a bash completion script for the borgmatic command. Produce this by
    introspecting borgmatic's command-line argument parsers.
    """
    import argparse
    import sys
    import textwrap

    def get_parser():
        """Return the root argument parser for borgmatic."""
        from borgmatic.commands import borgmatic

        return borgmatic.get_parser()

    def get_commands(parser):
        """Get the subcommands from the parser."""
        commands = []
        for action in parser._subparsers._actions:
            if isinstance(action, argparse._SubParsersAction):
                commands.extend(action.choices.keys())
        return sorted(commands)

    def get_flags(parser):
        """Get the flags/options from the parser."""
        flags = []
        for action in parser._actions:
            if isinstance(action, argparse.Action):
                if action.option_strings:
                    flags.extend(action.option_strings)
        return sorted(set(flags))

    def format_completion(command, flags):
        """Format the completion output."""
        return f'{command} {" ".join(flags)}'

    parser = get_parser()
    commands = get_commands(parser)
    flags = get_flags(parser)

    completion_script = textwrap.dedent('''\
    #!/bin/bash
    # bash completion for borgmatic

    _borgmatic_completion()
    {{
        local cur prev words cword
        _get_comp_words_by_ref -n : cur prev words cword

        local commands="{commands}"
        local flags="{flags}"

        case $prev in
            *)
            COMPREPLY=( $(compgen -W "$commands $flags" -- "$cur") )
            ;;
        esac
    }}

    complete -F _borgmatic_completion borgmatic
    '''.format(commands=' '.join(commands), flags=' '.join(flags))

    return completion_script

