import re

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import os
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:  # POSIX style
        # POSIX shell splitting pattern
        pattern = r'''([^\s"\\]*(?:"[^"\\]*(?:\\.[^"\\]*)*"?[^\s"\\]*)*|[^^\s"\\]+)'''
        # More robust POSIX pattern
        pattern = r'''((?:[^"\\]|\\.)*"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[^\s"']+)+'''
        # Even more robust pattern for POSIX
        pattern = r'''((?:"[^"\\]*(?:\\.[^"\\]*)*"|(?:[^"\\]|\\.)+)|'(?:[^'\\]|\\.)*'|[^\s]+)'''
        # Final robust POSIX pattern
        pattern = r'''((?:"[^"\\]*(?:\\.[^"\\]*)*"|(?:[^"\\]|\\.)+)|'(?:[^'\\]|\\.)*'|[^\s]+)'''

        # Use a more reliable approach for POSIX
        result = []
        i = 0
        n = len(s)
        while i < n:
            # Skip whitespace
            while i < n and s[i] in ' \t':
                i += 1
            if i >= n:
                break

            # Check for quoted strings
            if s[i] == '"':
                i += 1  # skip opening quote
                arg = []
                while i < n:
                    if s[i] == '\\' and i + 1 < n:
                        arg.append(s[i+1])
                        i += 2
                    elif s[i] == '"':
                        i += 1  # skip closing quote
                        break
                    else:
                        arg.append(s[i])
                        i += 1
                result.append(''.join(arg))
            elif s[i] == "'":
                i += 1  # skip opening quote
                arg = []
                while i < n:
                    if s[i] == "'" or (s[i] == '\\' and i + 1 < n and s[i+1] == "'"):
                        if s[i] == "'":
                            i += 1
                            break
                        else:
                            arg.append(s[i+1])
                            i += 2
                    else:
                        arg.append(s[i])
                        i += 1
                result.append(''.join(arg))
            else:
                # Unquoted argument
                arg = []
                while i < n and s[i] not in ' \t':
                    if s[i] == '\\' and i + 1 < n:
                        # In POSIX, backslash only escapes in certain contexts
                        # For simplicity, handle common cases
                        if s[i+1] in '"\'\\':
                            arg.append(s[i+1])
                            i += 2
                        else:
                            arg.append(s[i])
                            i += 1
                    else:
                        arg.append(s[i])
                        i += 1
