            while i < n and s[i] in ' \t':
                i += 1
            if i >= n:
                break

            # Check for quoted strings
            if s[i] == '"':
                i += 1  # skip opening quote
                arg = []
                while i < n:
                    if s[i] == '"' and i + 1 < n and s[i+1] == '"':
                        # Escaped quote
                        arg.append('"')
                        i += 2
                    elif s[i] == '"':
                        i += 1  # skip closing quote
                        break
                    else:
