import sys

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform == 'win32':
            platform = 0
        else:
            platform = 1

    if platform == 1:  # POSIX style
        # Pattern for POSIX shell-like splitting
        pattern = r'''([^\s"']+)|"([^"]*)"|'([^']*)'|(\\.)'''
        result = []
        for match in re.finditer(pattern, s):
            groups = match.groups()
            if groups[0]:
                result.append(groups[0])
            elif groups[1]:
                result.append(groups[1])
            elif groups[2]:
                result.append(groups[2])
            elif groups[3]:
                result.append(groups[3])
        return result
    elif platform == 0:  # Windows/CMD style
        # Pattern for Windows command-line splitting
        # Handles quotes, backslashes, and spaces
        pattern = r'''((?:"[^"]*"?)|(?:'[^']*'?)|(?:\\[^\s]*?)|(?:[^\s"']+))'''
        result = []
        for match in re.finditer(pattern, s):
            token = match.group(1)
            # Process Windows-specific escaping
            if token.startswith('"') and token.endswith('"') and len(token) > 1:
                # Remove surrounding quotes and unescape internal quotes
                token = token[1:-1].replace('""', '"')
            elif token.startswith("'") and token.endswith("'") and len(token) > 1:
                # Remove surrounding single quotes
                token = token[1:-1]
            elif token.startswith('\\') and len(token) > 1:
                # Handle backslash-escaped characters
                token = token[1:]
            result.append(token)
        return result
    else:
        raise ValueError("Invalid platform value. Use 'this', 0 (Windows), or 1 (POSIX).")

