def prepare_repository_from_archive(archive_path, filename, tmp_path):
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.

    @param archive_path : archive file path
    @param filename: File name
    @param tmp_path: Temporary file path
    @return Repo URL
    """
    # Create a temporary directory if tmp_path is not provided
    if not tmp_path:
        tmp_dir = tempfile.mkdtemp()
    else:
        tmp_dir = tmp_path

    # Extract the archive
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        with tarfile.open(archive_path, 'r:gz') as tar:
            tar.extractall(tmp_dir)
    elif archive_path.endswith('.tar'):
        with tarfile.open(archive_path, 'r:') as tar:
            tar.extractall(tmp_dir)
    elif archive_path.endswith('.zip'):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            zip_ref.extractall(tmp_dir)

    # Construct the repo URL
    repo_url = f"file://{tmp_dir}"

    return repo_url

