import urllib.parse


def _parse_image_ref(image_href):
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not image_href:
        raise ValueError("image_href cannot be empty")

    parsed = urllib.parse.urlparse(image_href)

    if not parsed.scheme:
        raise ValueError("Invalid image_href: missing scheme")

    if parsed.scheme not in ('http', 'https'):
        raise ValueError("Invalid image_href: only http and https schemes are supported")

    netloc = parsed.netloc
    use_ssl = parsed.scheme == 'https'

    # Extract image_id from path
    path = parsed.path.strip('/')
    if not path:
        raise ValueError("Invalid image_href: missing image ID in path")

    # Handle cases like /v2/images/{image_id}
    parts = path.split('/')
    image_id = None
    for i, part in enumerate(parts):
        if part == 'images' and i + 1 < len(parts):
            image_id = parts[i + 1]
            break
    else:
        # If no 'images' path component found, use the last part of the path
        image_id = path.split('/')[-1]

    if not image_id:
        raise ValueError("Invalid image_href: could not extract image ID")

    return (image_id, netloc, use_ssl)

