def load_configurations(config_filenames):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configurations = {}
    records = []

    # Create a custom logging handler to capture log records
    class ListHandler(logging.Handler):
        def __init__(self, records_list):
            super().__init__()
            self.records_list = records_list

        def emit(self, record):
            self.records_list.append(record)

    # Set up logging to capture records
    logger = logging.getLogger('borgmatic')
    logger.setLevel(logging.ERROR)

    handler = ListHandler(records)
    formatter = logging.Formatter('%(levelname)s:%(name)s:%(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    for config_filename in config_filenames:
        try:
            if not os.path.exists(config_filename):
                logger.error(f"Configuration file '{config_filename}' does not exist")
                continue

            if not os.access(config_filename, os.R_OK):
                logger.error(f"Permission denied reading configuration file '{config_filename}'")
                continue

            with open(config_filename, 'r') as file:
                config = yaml.safe_load(file)
                if config is None:
                    config = {}
                configurations[config_filename] = config

        except yaml.YAMLError as e:
            logger.error(f"Error parsing configuration file '{config_filename}': {e}")
        except PermissionError:
            logger.error(f"Permission denied reading configuration file '{config_filename}'")
        except Exception as e:
            logger.error(f"Error reading configuration file '{config_filename}': {e}")

    return configurations, records

