def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    if other is None:
        if recompute or not hasattr(self, '_scale') or self._scale is None:
            # Compute scale as sum of bin contents multiplied by bin widths
            # For multi-dimensional histograms, compute the integral
            total = 0.0
            if self.dim == 1:
                for i, bin_content in enumerate(self.bins):
                    bin_width = self.edges[i+1] - self.edges[i]
                    total += bin_content * bin_width
            else:
                # For higher dimensions, assume uniform binning per dimension
                # and compute volume element for each bin
                # This is a simplified approach; actual implementation may vary
                volumes = [1.0]
                for dim in range(self.dim):
                    if dim == 0:
                        edges_dim = self.edges[dim]
                    else:
                        edges_dim = self.edges[dim]
                    widths = [edges_dim[i+1] - edges_dim[i] for i in range(len(edges_dim)-1)]
                    if dim == 0:
                        volumes = widths
                    else:
                        volumes = [v * w for v in volumes for w in widths]

                # Flatten bins if needed and compute sum
                bins_flat = self.bins
                if not isinstance(self.bins[0], (int, float, complex)):
                    # Multi-dimensional bins - flatten them
                    bins_flat = []
                    def flatten(lst):
                        for item in lst:
                            if isinstance(item, (int, float, complex)):
                                bins_flat.append(item)
                            else:
                                flatten(item)
                    flatten(self.bins)

                total = sum(b * v for b, v in zip(bins_flat, volumes))

            self._scale = total
        return self._scale
    else:
        # Rescale to other
        current_scale = self.scale(recompute=recompute)
        if current_scale == 0:
            from lena.core import LenaValueError
            raise LenaValueError("Cannot rescale histogram with zero scale")

        factor = other / current_scale
        # Rescale bins
        if self.dim == 1:
            self.bins = [bin_content * factor for bin_content in self.bins]
        else:
            # For multi-dimensional histograms
            def scale_recursive(bins_list, factor):
                if isinstance(bins_list[0], (int, float, complex)):
                    return [b * factor for b in bins_list]
                else:
                    return [scale_recursive(sublist, factor) for sublist in bins_list]
            self.bins = scale_recursive(self.bins, factor)

        # Update scale
        self._scale = other
        return other

