def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return self._scale

    if self._scale is None or self._scale == 0:
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale")

    # Rescale the last coordinate and its errors
    if hasattr(self, 'coords') and self.coords:
        # Get the last coordinate name
        coord_names = self._coord_names
        if coord_names:
            last_coord_name = coord_names[-1]

            # Rescale the last coordinate
            new_coords = []
            for coord in self.coords:
                if isinstance(coord, tuple):
                    coord_list = list(coord)
                    if len(coord_list) > 1:
                        coord_list[-1] = coord_list[-1] * other / self._scale
                    elif len(coord_list) == 1:
                        coord_list[0] = coord_list[0] * other / self._scale
                    new_coords.append(tuple(coord_list))
                else:
                    new_coords.append(coord)

            # Update the coordinates
            self.coords = new_coords

            # Rescale the errors
            if hasattr(self, '_parsed_error_names') and self._parsed_error_names:
                for err_name in self._parsed_error_names:
                    if hasattr(self, err_name):
                        setattr(self, err_name, [val * other / self._scale for val in getattr(self, err_name)])

    self._scale = other

