def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=None, scale=False):
    from lena.structures import histogram
    from lena.graph import Graph

    if not isinstance(hist, histogram):
        raise TypeError("hist must be a histogram")

    if make_value is None:
        make_value = lambda bin_: bin_.content

    # Determine dimension from histogram
    dim = hist.dimension

    # Prepare data for graph
    data = []

    # Iterate over bins
    for bin_info in hist:
        bin_ = bin_info.bin
        coord = bin_info.coordinate

        # Get graph point coordinate
        if get_coordinate == "left":
            x = coord[0]
        elif get_coordinate == "right":
            x = coord[1]
        elif get_coordinate == "middle":
            x = (coord[0] + coord[1]) / 2
        else:
            raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

        # Get value(s) from bin
        value = make_value(bin_)

        # Ensure value is a tuple for consistency
        if not isinstance(value, tuple):
            value = (value,)

        # Construct point: (x, value...)
        point = (x,) + value
        data.append(point)

    # Set field names
    if field_names is None:
        # Default field names based on dimension
        if dim == 1:
            field_names = ("x", "y")
        else:
            # For higher dimensions, use generic names
            field_names = tuple("x{}".format(i) for i in range(1, len(data[0]) + 1)) if data else ()
    else:
        # Validate field_names length
        if data and len(field_names) != len(data[0]):
            raise ValueError("field_names must have length equal to the dimension of the result")

    # Set scale
    if scale is True:
        scale = hist.scale

    # Create and return graph
    graph = Graph(data, field_names=field_names, scale=scale)
    return graph

