        return dt

    def _parse_isodate(self, dt_str):
        dt_str = dt_str.strip()
        if not dt_str:
            raise ValueError("Date string cannot be empty")

        # Try common formats first
        result = self._parse_isodate_common(dt_str)
        if result is not None:
            return result

        # Try uncommon formats
        return self._parse_isodate_uncommon(dt_str)

    def _parse_isodate_common(self, dt_str):
        dt_str = dt_str.strip()

        # YYYY-MM-DD or YYYYMMDD
        match = re.match(r'^(\d{4})-?(\d{2})-?(\d{2})$', dt_str)
        if match:
            year, month, day = map(int, match.groups())
            try:
                return date(year, month, day)
            except ValueError:
                pass

        # YYYY-MM or YYYYMM
        match = re.match(r'^(\d{4})-?(\d{2})$', dt_str)
        if match:
            year, month = map(int, match.groups())
            try:
                return date(year, month, 1)
            except ValueError:
                pass

        # YYYY
        match = re.match(r'^(\d{4})$', dt_str)
        if match:
            year = int(match.group(1))
            try:
                return date(year, 1, 1)
            except ValueError:
                pass

        return None

    def _parse_isodate_uncommon(self, dt_str):
        dt_str = dt_str.strip()

        # YYYY-Www or YYYYWww
        match = re.match(r'^(\d{4})-?W(\d{2})$', dt_str)
        if match:
            year, week = map(int, match.groups())
            try:
                return self._calculate_weekdate(year, week, 0)
            except ValueError:
                pass

        # YYYY-Www-D or YYYYWwwD
        match = re.match(r'^(\d{2})-?W(\d{2})-?(\d)$', dt_str)
        if match:
            year, week, day = map(int, match.groups())
            try:
                return self._calculate_weekdate(year, week, day)
            except ValueError:
                pass

        return None

    def _calculate_weekdate(self, year, week, day):
        # January 4th is always in week 1
        jan4 = date(year, 1, 4)
        # Find the Monday of the week containing January 4th
        days_to_monday = jan4.weekday()
        week1_monday = jan4 - timedelta(days=days_to_monday)
        # Calculate the date for the requested week and day
        week_date = week1_monday + timedelta(weeks=week-1, days=day)
        return date(week_date.year, week_date.month, week_date.day)

    def _parse_isotime(self, timestr):
        timestr = timestr.strip()

