from federation.utils.logger import logger

USER_AGENT = "Federation/1.0 (+https://github.com/federation/federation)"


def fetch_content_type(url: str) -> typing.Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.

    :param url: The URL to fetch the content type from.
    :return: The content type string or None if not available.
    """
    headers = {
        "User-Agent": USER_AGENT
    }
    try:
        response = requests.head(url, headers=headers, timeout=10)
        return response.headers.get("Content-Type")
    except (requests.RequestException, ValueError):
        return None

