def parse_diaspora_webfinger(document: str) -> typing.Optional[str]:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try parsing as JSON first (new format)
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            links = data.get("links", [])
            if isinstance(links, list):
                for link in links:
                    if isinstance(link, dict):
                        rel = link.get("rel")
                        href = link.get("href")
                        if rel == "http://microformats.org/profile/hcard" and href:
                            return href
    except (json.JSONDecodeError, TypeError):
        pass

    # Try parsing as XRD (old format)
    try:
        root = ET.fromstring(document)
        # Handle XRD format
        for child in root:
            if child.tag.endswith("Link"):
                for grandchild in child:
                    if grandchild.tag.endswith("href"):
                        if child.get("rel") == "http://microformats.org/profile/hcard":
                            return grandchild.text
    except (ET.ParseError, TypeError):
        pass

    return None

