from typing import Dict, Optional

logger = logging.getLogger(__name__)


def retrieve_and_parse_diaspora_webfinger(handle: str) -> Dict:
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Construct the webfinger URL from the handle
    # Handle format: user@domain.tld
    if "@" not in handle:
        logger.error(f"Invalid handle format: {handle}")
        return {}

    domain = handle.split("@")[1]
    webfinger_url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"

    try:
        # Retrieve the webfinger document
        with urllib.request.urlopen(webfinger_url) as response:
            document = response.read().decode('utf-8')

        # Parse the webfinger document
        return _parse_webfinger_document(document, handle)

    except Exception as e:
        logger.error(f"Failed to retrieve webfinger document for {handle}: {e}")
        return {}


def _parse_webfinger_document(document: str, handle: str) -> Dict:
    """
    Parse a webfinger document.

    :param document: The webfinger document as a string
    :param handle: The handle that was requested
    :return: A dictionary with the parsed data
    """
    try:
        # Try to parse as JSON first (most common for Diaspora)
        data = json.loads(document)

        # Validate that we have the expected structure
        if "subject" in data and data["subject"] == f"acct:{handle}":
            return data
        else:
            logger.warning(f"Unexpected webfinger response for {handle}: missing subject field")
            return {}

    except json.JSONDecodeError:
        # If not JSON, try to parse as XML (XRD format)
        try:
            root = ET.fromstring(document)
            # Extract relevant information from XML
            result = {"subject": handle}
            # Process the XML structure
            for child in root:
                if child.tag.endswith("Link"):
                    link_data = {}
                    for attr in child.attrib:
                        link_data[attr] = child.attrib[attr]
                    if "rel" in link_data:
                        if "links" not in result:
                    result["links"] = []
                        result["links"].append(link_data)
            return result
        except ET.ParseError:
            logger.error(f"Failed to parse webfinger document for {handle}: Invalid XML")
            return {}

