import infrared


class IRValidatorException(Exception):
    """Exception raised when validation fails."""
    pass


class IRValidator:
    """Validator for infrared spec files."""

    @classmethod
    def validate_from_file(cls, yaml_file):
        """Validate spec from file."""
        with open(yaml_file, 'r') as f:
            spec_content = f.read()
        return cls.validate_from_content(spec_content)

    @classmethod
    def validate_from_content(cls, spec_content):
        """Validate spec from content string."""
        try:
            spec_dict = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Invalid YAML syntax: {e}")

        if not isinstance(spec_dict, dict):
            raise IRValidatorException("Spec content must be a YAML dictionary.")

        required_fields = [
            "name", "version", "description", "author", "license",
            "inputs", "steps"
        ]

        missing_fields = [field for field in required_fields if field not in spec_dict]
        if missing_fields:
            raise IRValidatorException(
                f"Missing required fields in spec: {', '.join(missing_fields)}"
            )

        return spec_dict

