from infrared.core.utils import IRValidatorException


class Validators:
    @classmethod
    def validate_from_file(cls, yaml_file):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not os.path.exists(yaml_file):
            raise IRValidatorException("File does not exist: %s" % yaml_file)

        try:
            with open(yaml_file, 'r') as f:
                content = yaml.safe_load(f)
        except yaml.YAMLError as e:
            raise IRValidatorException("Failed to parse YAML file %s: %s" % (yaml_file, str(e)))

        return cls.validate_from_content(content)

    @classmethod
    def validate_from_content(cls, file_content):
        """Validates that the content has all required fields

        :param file_content: Dictionary with YAML content
        :raise IRValidatorException: when mandatory data is missing in content
        :return: Dictionary with validated data
        """
        if file_content is None:
            raise IRValidatorException("YAML content is empty")

        return file_content

