def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if 'include' in parser_dict:
        include_spec = parser_dict['include']
        if isinstance(include_spec, str):
            # Handle string reference to another parser spec
            included_parser = self.spec_dict.get(include_spec)
            if included_parser:
                # Merge included parser's options
                for key, value in included_parser.items():
                    if key not in parser_dict:
                        parser_dict[key] = value
        elif isinstance(include_spec, list):
            # Handle list of parser references
            for ref in include_spec:
                included_parser = self.spec_dict.get(ref)
                if included_parser:
                    for key, value in included_parser.items():
                        if key not in parser_dict:
                            parser_dict[key] = value
        # Remove the include directive after processing
        parser_dict.pop('include', None)

