def _run_playbook(vars_dict, cli_args, ir_workspace, ir_plugin):
    import subprocess
    import json
    import os
    import tempfile

    # Create a temporary file for extra vars
    with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as tmpfile:
        json.dump(vars_dict, tmpfile)
        extra_vars_file = tmpfile.name

    try:
        # Build the ansible-playbook command
        cmd = ['ansible-playbook'] + cli_args
        if extra_vars_file:
            cmd.extend(['-e', '@' + extra_vars_file])

        # Get the playbook path from workspace or plugin
        playbook_path = ir_workspace.playbook_path if hasattr(ir_workspace, 'playbook_path') else ir_plugin.playbook_path
        if playbook_path:
            cmd.append(playbook_path)

        # Set environment variables
        env = os.environ.copy()
        env.update({
            'ANSIBLE_CONFIG': ir_workspace.ansible_config_path if hasattr(ir_workspace, 'ansible_config_path') else ir_plugin.ansible_config_path,
            'INFRARED_WORKSPACE': ir_workspace.name if hasattr(ir_workspace, 'name') else '',
            'INFRARED_PLUGIN': ir_plugin.name if hasattr(ir_plugin, 'name') else ''
        })

        # Run the command
        result = subprocess.run(
            cmd,
            env=env,
            capture_output=True,
            text=True
        )

        # Parse and return results
        if result.returncode == 0:
            try:
                # Try to parse JSON output if available
                return json.loads(result.stdout)
            except json.JSONDecodeError:
                return {'stdout': result.stdout, 'stderr': result.stderr, 'returncode': result.returncode}
        else:
            raise Exception(f"Ansible playbook failed with return code {result.returncode}: {result.stderr}")
    finally:
        # Clean up temporary file
        if os.path.exists(extra_vars_file):
            os.unlink(extra_vars_file)

