def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Import required modules
    import infrared

    # Get the parser to determine the correct types
    parser = self._get_parser(parser_name)

    # Iterate through the values_dict and convert types
    for key, value in values_dict.items():
        # Skip if value is None
        if value is None:
            continue

        # Try to find the argument specification
        arg_spec = self._get_arg_spec(parser, key)

        if arg_spec:
            # Get the type function from the specification
            type_func = arg_spec.get('type', str)

            # Convert the value to the correct type
            try:
                # Handle special cases
                if type_func == int:
                    values_dict[key] = int(value)
                elif type_func == float:
                    values_dict[key] = float(value)
                elif type_func == bool:
                    # Handle boolean conversion
                    if isinstance(value, str):
                        values_dict[key] = value.lower() in ('true', 'yes', '1')
                    else:
                        values_dict[key] = bool(value)
                elif type_func == list:
                    # Handle list conversion
                    if isinstance(value, str):
                        # Try to parse as comma-separated list
                        values_dict[key] = [item.strip() for item in value.split(',')]
                    else:
                        values_dict[key] = list(value)
                else:
                    # For custom types, try direct conversion
                    values_dict[key] = type_func(value)
            except (ValueError, TypeError):
                # If conversion fails, keep original value
                pass
        else:
            # If no specification found, try to infer type
            if isinstance(value, str):
                # Try to convert to int first
                try:
                    int_val = int(value)
                    values_dict[key] = int_val
                except ValueError:
                    # Keep as string
                    pass

